content:
:root {
  --primary-color: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #6b7280;
  --border-color: #e5e7eb;
  --success-color: #10b981;
  --error-color: #ef4444;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

.app-container {
  width: 100%;
  max-width: 600px;
  padding: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.header {
  margin-bottom: 24px;
  text-align: center;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary-color);
}

.game-box {
  background-color: var(--card-bg);
  width: 100%;
  border-radius: 12px;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.stats-bar {
  display: flex;
  justify-content: space-between;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--text-muted);
  background-color: var(--bg-color);
  padding: 12px 16px;
  border-radius: 8px;
}

.timer {
  color: var(--primary-color);
}

.score {
  color: var(--success-color);
}

.word-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 32px 16px;
  background-color: #f9fafb;
  border: 2px dashed var(--border-color);
  border-radius: 8px;
  gap: 12px;
}

.japanese {
  font-size: 1.5rem;
  font-weight: 600;
  color: var(--text-main);
}

.romaji {
  font-size: 2rem;
  font-family: monospace;
  letter-spacing: 0.1em;
  font-weight: 700;
}

.typed-char {
  color: var(--text-muted);
  text-decoration: underline;
}

.remaining-char {
  color: var(--text-main);
}

.input-area {
  width: 100%;
  padding: 12px 16px;
  font-size: 1.25rem;
  border: 2px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s;
  text-align: center;
}

.input-area:focus {
  border-color: var(--primary-color);
}

@keyframes shake {
  0%, 100% { transform: translateX(0); }
  20%, 60% { transform: translateX(-4px); }
  40%, 80% { transform: translateX(4px); }
}

.input-error {
  border-color: var(--error-color) !important;
  animation: shake 0.3s ease-in-out;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  font-size: 1rem;
  font-weight: 600;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background-color: var(--primary-color);
  color: white;
  width: 100%;
}

.btn-primary:hover {
  background-color: var(--primary-hover);
}

.result-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  text-align: center;
}

.result-card h2 {
  font-size: 1.75rem;
  color: var(--primary-color);
}

.result-stats {
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 1.125rem;
  color: var(--text-muted);
  margin-bottom: 8px;
}

export interface Word {
  id: string;
  japanese: string;
  romaji: string;
}

export interface GameSettings {
  timeLimit: number;
  difficulty?: string;
}

export interface GameState {
  status: 'idle' | 'playing' | 'result';
  score: number;
  timeLeft: number;
  typedCharsCount: number;
  totalErrors: number;
}

import { useState, useEffect, useRef } from 'react';
import { Word, GameState } from '../types';

const INITIAL_WORDS: Word[] = [
  { id: '1', japanese: 'りんご', romaji: 'ringo' },
  { id: '2', japanese: 'ねこ', romaji: 'neko' },
  { id: '3', japanese: 'いぬ', romaji: 'inu' },
  { id: '4', japanese: 'ぷろぐらみんぐ', romaji: 'programming' },
  { id: '5', japanese: 'りあくと', romaji: 'react' },
  { id: '6', japanese: 'すし', romaji: 'sushi' },
  { id: '7', japanese: 'らーめん', romaji: 'ramen' },
  { id: '8', japanese: 'ぱいそん', romaji: 'python' },
  { id: '9', japanese: 'さくら', romaji: 'sakura' },
  { id: '10', japanese: 'きつね', romaji: 'kitsune' },
];

export default function TypingGame() {
  const [gameState, setGameState] = useState<GameState>({
    status: 'idle',
    score: 0,
    timeLeft: 60,
    typedCharsCount: 0,
    totalErrors: 0,
  });

  const [words, setWords] = useState<Word[]>([]);
  const [currentWordIndex, setCurrentWordIndex] = useState(0);
  const [inputVal, setInputVal] = useState('');
  const [isError, setIsError] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const shuffleWords = () => {
    const shuffled = [...INITIAL_WORDS].sort(() => Math.random() - 0.5);
    setWords(shuffled);
  };

  const startGame = () => {
    shuffleWords();
    setGameState({
      status: 'playing',
      score: 0,
      timeLeft: 60,
      typedCharsCount: 0,
      totalErrors: 0,
    });
    setCurrentWordIndex(0);
    setInputVal('');
    setIsError(false);
    setTimeout(() => {
      inputRef.current?.focus();
    }, 100);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter' && (gameState.status === 'idle' || gameState.status === 'result')) {
        startGame();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState.status]);

  useEffect(() => {
    if (gameState.status !== 'playing') return;

    if (gameState.timeLeft <= 0) {
      setGameState(prev => ({ ...prev, status: 'result' }));
      return;
    }

    const timer = setInterval(() => {
      setGameState(prev => {
        if (prev.timeLeft <= 1) {
          clearInterval(timer);
          return { ...prev, timeLeft: 0, status: 'result' };
        }
        return { ...prev, timeLeft: prev.timeLeft - 1 };
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [gameState.status, gameState.timeLeft]);

  const currentWord = words[currentWordIndex] || { japanese: '', romaji: '' };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (gameState.status !== 'playing') return;
    const value = e.target.value;

    if (currentWord.romaji.startsWith(value)) {
      setInputVal(value);
      setIsError(false);
      if (value === currentWord.romaji) {
        setGameState(prev => ({
          ...prev,
          score: prev.score + currentWord.romaji.length,
          typedCharsCount: prev.typedCharsCount + currentWord.romaji.length,
        }));
        setInputVal('');
        setIsError(false);
        setCurrentWordIndex(prev => (prev + 1) % words.length);
      }
    } else {
      if (value.length > inputVal.length) {
        setIsError(true);
        setTimeout(() => setIsError(false), 300);
        setGameState(prev => ({
          ...prev,
          totalErrors: prev.totalErrors + 1,
        }));
      }
    }
  };

  return (
    <div className="game-box">
      {gameState.status === 'idle' && (
        <div className="result-card">
          <h2>ローマ字タイピングゲーム</h2>
          <p>60秒間でできるだけ多くの文字を正しく打ち込もう！</p>
          <button className="btn btn-primary" onClick={startGame}>
            ゲームスタート
          </button>
        </div>
      )}

      {gameState.status === 'playing' && (
        <>
          <div className="stats-bar">
            <div className="timer">残り時間: {gameState.timeLeft}秒</div>
            <div className="score">スコア: {gameState.score}</div>
          </div>

          <div className="word-card">
            <div className="japanese">{currentWord.japanese}</div>
            <div className="romaji">
              <span className="typed-char">{currentWord.romaji.substring(0, inputVal.length)}</span>
              <span className="remaining-char">{currentWord.romaji.substring(inputVal.length)}</span>
            </div>
          </div>

          <input
            ref={inputRef}
            type="text"
            className={`input-area ${isError ? 'input-error' : ''}`}
            value={inputVal}
            onChange={handleInputChange}
            placeholder="ここに入力..."
            autoFocus
            spellCheck={false}
            autoComplete="off"
            autoCapitalize="off"
          />
        </>
      )}

      {gameState.status === 'result' && (
        <div className="result-card">
          <h2>ゲーム終了！</h2>
          <div className="result-stats">
            <p>スコア（正解文字数）: <strong>{gameState.score}</strong> 文字</p>
            <p>ミス入力回数: <strong>{gameState.totalErrors}</strong> 回</p>
          </div>
          <button className="btn btn-primary" onClick={startGame}>
            もう一度プレイ
          </button>
        </div>
      )}
    </div>
  );
}

import TypingGame from './components/TypingGame';
import './index.css';

export default function App() {
  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">タイピングゲーム</h1>
      </header>
      <TypingGame />
      <footer style={{ marginTop: '24px', textAlign: 'center', color: 'var(--text-muted)', fontSize: '0.875rem' }}>
        <p>ローマ字タイピング練習アプリ - 60秒で限界に挑戦しよう！</p>
      </footer>
    </div>
  );
}
